import { b64u } from '../hash';
import { publicKeyOf } from '../keys';
import { instantiateTemplate, templateDefError, signTemplate, signTighten, templateDigest, templateRefError, slotsDigest, verifyTemplate, verifyTighten, resolveLink, type TemplateDef, type TemplateRegistry } from '../policy-link';

/**
 * Shared vectors for linked policy templates (conformance/policy-link-vectors.json): the template digest, instantiation
 * (accepted fills and every refusal), signed-template and tighten-overlay verification under a fixed test key, and link
 * resolution. Generated by scripts/gen-conformance-policy-link.ts from the TypeScript reference.
 */

const SECRET = new Uint8Array(32).fill(7);
const OTHER = new Uint8Array(32).fill(9);
export const PUB = b64u(publicKeyOf(SECRET));
const OTHER_PUB = b64u(publicKeyOf(OTHER));

export const TEMPLATE: TemplateDef = {
  v: 1,
  kind: 'pca-policy-template',
  id: 'support_agent',
  version: '3',
  slots: {
    acct: { type: 'string' },
    cap: { type: 'integer', min: 1, max: 1000 },
    region: { type: 'string', values: ['eu', 'us'] },
    verbs: { type: 'set', values: ['mail.draft', 'mail.send', 'chat.post'] },
  },
  body: {
    predicates: [
      { verb: { $slot: 'verbs' } as never, resource: { $slot: 'acct', pre: '/acct/', post: '/*' } as never, where: [{ field: 'action.params.amount', op: 'lte', value: { $slot: 'cap' } as never }, { field: 'env.region', op: 'eq', value: { $slot: 'region' } as never }] },
    ],
    caveats: [{ type: 'rate', max: 50, per_secs: 86400 }],
  },
};

const FILL = { acct: 'a42', cap: 200, region: 'eu', verbs: ['mail.draft', 'mail.send'] };

export function buildPolicyLinkVectors(): unknown {
  const bad = (slots: Record<string, unknown>) => instantiateTemplate(TEMPLATE, slots);
  const inst: Array<{ name: string; slots: Record<string, unknown> }> = [
    { name: 'a complete fill', slots: FILL },
    { name: 'an unfilled slot', slots: { acct: 'a42', cap: 200, region: 'eu' } },
    { name: 'an undeclared slot', slots: { ...FILL, extra: 1 } },
    { name: 'integer above its maximum', slots: { ...FILL, cap: 1001 } },
    { name: 'integer below its minimum', slots: { ...FILL, cap: 0 } },
    { name: 'a float for an integer', slots: { ...FILL, cap: 2.5 } },
    { name: 'a string outside its closed set', slots: { ...FILL, region: 'ap' } },
    { name: 'a set member outside the closed set', slots: { ...FILL, verbs: ['mail.send', 'bank.wire'] } },
    { name: 'a set with duplicates', slots: { ...FILL, verbs: ['mail.send', 'mail.send'] } },
    { name: 'an empty set', slots: { ...FILL, verbs: [] } },
    { name: 'a wildcard spliced into a resource', slots: { ...FILL, acct: '*' } },
    { name: 'a wildcard inside a resource value', slots: { ...FILL, acct: 'a*' } },
    { name: 'a string slot given a number', slots: { ...FILL, acct: 5 } },
    { name: 'a regex matcher for a resource', slots: { ...FILL, acct: 're:.*' } },
  ];
  const signed = signTemplate(TEMPLATE, SECRET, PUB);
  const digest = templateDigest(TEMPLATE);
  const reg = (over: Partial<TemplateRegistry> = {}): TemplateRegistry => ({ templates: { [digest]: signed }, trusted: [PUB], ...over });
  const ref = { template_id: 'support_agent', version_digest: digest, slots: FILL };
  const bound = { template_id: 'support_agent', version_digest: digest, bind_params_digest: slotsDigest(FILL) };
  const overlay = signTighten({ v: 1, kind: 'pca-template-tighten', template_id: 'support_agent', version_digest: digest, add_where: [{ field: 'env.tier', op: 'ne', value: 'frozen' }], add_caveats: [{ type: 'max_blast_radius', max: 0.3 }] }, SECRET, PUB);
  const resolve = (name: string, r: unknown, registry: TemplateRegistry) => ({ name, ref: r, registry, expect: (() => { const x = resolveLink(r as never, registry); return x.ok ? { ok: true, overlays: x.overlays, policy: x.policy } : { ok: false, reason: x.reason }; })() });
  const withBody = (body: unknown): TemplateDef => ({ ...TEMPLATE, body: body as never });
  const defErrors: Array<{ name: string; def: unknown }> = [
    { name: 'the example template', def: TEMPLATE },
    { name: 'a prototype key in the body', def: withBody(JSON.parse('{"predicates":[{"verb":{"$slot":"verbs"},"resource":{"$slot":"acct","pre":"/acct/","post":"/*"},"__proto__":{"x":1},"where":[{"field":"action.params.amount","op":"lte","value":{"$slot":"cap"}},{"field":"env.region","op":"eq","value":{"$slot":"region"}}]}]}')) },
    { name: 'a slot declared but never used', def: { ...TEMPLATE, slots: { ...TEMPLATE.slots, extra: { type: 'string' } } } },
    { name: 'a placeholder for an undeclared slot', def: withBody({ predicates: [{ verb: { $slot: 'nope' } }] }) },
    { name: 'a placeholder with an unknown member', def: { ...TEMPLATE, slots: { acct: { type: 'string' } }, body: { predicates: [{ verb: { $slot: 'acct', other: 1 } }] } } },
    { name: 'a set slot without a closed list', def: { ...TEMPLATE, slots: { ...TEMPLATE.slots, verbs: { type: 'set' } } } },
    { name: 'a bad slot name', def: { ...TEMPLATE, slots: { A: { type: 'string' } } } },
    { name: 'a bad template id', def: { ...TEMPLATE, id: 'Bad Id' } },
    { name: 'not an object', def: null },
  ];
  return {
    version: 1,
    note: 'Generated by scripts/gen-conformance-policy-link.ts. `template`: the definition and its digest. `instantiate`: fills and refusals. `verify`: signed template / overlay verification. `resolve`: reference to policy.',
    public_key: PUB,
    template: { def: TEMPLATE, digest },
    def_errors: defErrors.map((d) => ({ ...d, expect: templateDefError(d.def) })),
    instantiate: inst.map((i) => ({ ...i, expect: (() => { const r = bad(i.slots); return r.ok ? { ok: true, policy: r.policy } : { ok: false, reason: r.reason }; })() })),
    verify: [
      { name: 'signed template under a trusted key', kind: 'template', signed, trusted: [PUB], expect: verifyTemplate(signed, [PUB]) },
      { name: 'signed template under an untrusted key', kind: 'template', signed, trusted: [OTHER_PUB], expect: verifyTemplate(signed, [OTHER_PUB]) },
      { name: 'template edited after signing', kind: 'template', signed: { ...signed, def: { ...TEMPLATE, version: '4' } }, trusted: [PUB], expect: verifyTemplate({ ...signed, def: { ...TEMPLATE, version: '4' } }, [PUB]) },
      { name: 'template signed by another key', kind: 'template', signed: signTemplate(TEMPLATE, OTHER, OTHER_PUB), trusted: [PUB], expect: verifyTemplate(signTemplate(TEMPLATE, OTHER, OTHER_PUB), [PUB]) },
      { name: 'tighten overlay under a trusted key', kind: 'overlay', signed: overlay, trusted: [PUB], expect: verifyTighten(overlay, [PUB]) },
      { name: 'tighten overlay edited after signing', kind: 'overlay', signed: { ...overlay, overlay: { ...overlay.overlay, add_where: [] } }, trusted: [PUB], expect: verifyTighten({ ...overlay, overlay: { ...overlay.overlay, add_where: [] } }, [PUB]) },
    ],
    ref_errors: [
      { name: 'a well formed reference', ref, expect: templateRefError(ref) },
      { name: 'unknown member', ref: { ...ref, extra: 1 }, expect: templateRefError({ ...ref, extra: 1 }) },
      { name: 'slots not an object', ref: { ...ref, slots: [] }, expect: templateRefError({ ...ref, slots: [] }) },
      { name: 'a bound reference', ref: bound, expect: templateRefError(bound) },
      { name: 'slots and a bound digest together', ref: { ...bound, slots: FILL }, expect: templateRefError({ ...bound, slots: FILL }) },
      { name: 'an empty bound digest', ref: { ...bound, bind_params_digest: '' }, expect: templateRefError({ ...bound, bind_params_digest: '' }) },
      { name: 'a non-string bound digest', ref: { ...bound, bind_params_digest: 5 }, expect: templateRefError({ ...bound, bind_params_digest: 5 }) },
      { name: 'neither slots nor a bound digest', ref: { template_id: 'support_agent', version_digest: digest }, expect: templateRefError({ template_id: 'support_agent', version_digest: digest }) },
    ],
    resolve: [
      resolve('a reference resolves to the instantiation', ref, reg()),
      resolve('a registry without the version', ref, reg({ templates: {} })),
      resolve('an untrusted registry signer', ref, reg({ trusted: [OTHER_PUB] })),
      resolve('a verified tighten overlay is applied to every predicate and the caveats', ref, reg({ overlays: [overlay] })),
      resolve('an overlay for another version is ignored', ref, reg({ overlays: [{ ...overlay, overlay: { ...overlay.overlay, version_digest: 'other' } }] })),
      resolve('an invalid overlay for this version is a refusal', ref, reg({ overlays: [{ ...overlay, sig: overlay.sig.slice(1) + 'A' }] })),
      resolve('a reference with a bad fill', { ...ref, slots: { ...FILL, cap: 5000 } }, reg()),
      resolve('a bound reference resolves to the same instantiation as the inline one', bound, reg({ params: { [slotsDigest(FILL)]: FILL } })),
      resolve('a bound reference with no parameter object', bound, reg()),
      resolve('a bound reference whose parameter object was edited', bound, reg({ params: { [slotsDigest(FILL)]: { ...FILL, cap: 201 } } })),
      resolve('a bound reference whose object is under another digest', { ...bound, bind_params_digest: 'other' }, reg({ params: { other: FILL } })),
      resolve('a bound reference to an object that fails the template', { ...bound, bind_params_digest: slotsDigest({ ...FILL, cap: 5000 }) }, reg({ params: { [slotsDigest({ ...FILL, cap: 5000 })]: { ...FILL, cap: 5000 } } })),
    ],
  };
}
